-- Typed record payloads preserve the recovered MVP schema. Server validation enforces relationships.
CREATE TABLE records (organization_id CHAR(36) NOT NULL, kind VARCHAR(30) NOT NULL, id CHAR(36) NOT NULL, owner_id CHAR(36) NOT NULL, version INT NOT NULL, archived BOOLEAN NOT NULL DEFAULT 0, payload JSON NOT NULL, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(organization_id,kind,id), INDEX(organization_id,kind,archived), FOREIGN KEY(organization_id,owner_id) REFERENCES accounts(organization_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE record_versions (organization_id CHAR(36) NOT NULL, kind VARCHAR(30) NOT NULL, record_id CHAR(36) NOT NULL, version INT NOT NULL, payload JSON NOT NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(organization_id,kind,record_id,version), FOREIGN KEY(organization_id,kind,record_id) REFERENCES records(organization_id,kind,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE media_assets (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, creator_id CHAR(36) NOT NULL, stored_path VARCHAR(255) NOT NULL, thumbnail_path VARCHAR(255) NULL, sha256 CHAR(64) NOT NULL, mime VARCHAR(30) NOT NULL, byte_size BIGINT UNSIGNED NOT NULL, width INT NOT NULL, height INT NOT NULL, name VARCHAR(255) NOT NULL, archived BOOLEAN NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL, INDEX(organization_id,sha256), UNIQUE KEY(organization_id,id), FOREIGN KEY(organization_id,creator_id) REFERENCES accounts(organization_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sync_changes (organization_id CHAR(36) NOT NULL, sequence BIGINT UNSIGNED NOT NULL, kind VARCHAR(30) NOT NULL, record_id CHAR(36) NOT NULL, PRIMARY KEY(organization_id,sequence), FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
